using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
namespace FrameScout {
 public static class FrameWindows {
  public static BitmapSource Bitmap(byte[] bytes) {var b=new BitmapImage();using(var ms=new MemoryStream(bytes)){b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.StreamSource=ms;b.EndInit();b.Freeze();}return b;}
  public static Window Dialog(Window owner,string title,int width,int height) {var w=new Window {Owner=owner,Title=title,Width=Math.Min(width,SystemParameters.WorkArea.Width*0.95),Height=Math.Min(height,SystemParameters.WorkArea.Height*0.95),WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=owner.Background,Foreground=owner.Foreground,FontFamily=owner.FontFamily};w.Resources.MergedDictionaries.Add(owner.Resources);return w;}
  public static void Zoom(Window owner,ImageSource source,string title) {var w=Dialog(owner,"画面放大 · "+title,1150,820);var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());var tools=new WrapPanel {Margin=new Thickness(12)};var scroll=new ScrollViewer {HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Background=Brushes.Black};var image=new Image {Source=source,Stretch=Stretch.Uniform};scroll.Content=image;double scale=1;Action fit=()=> {scale=1;image.LayoutTransform=Transform.Identity;image.Width=double.NaN;image.Height=Math.Max(100,w.ActualHeight-100);};Action<double> zoom=value=> {scale=Math.Max(0.1,Math.Min(12,value));image.Height=double.NaN;image.Width=((BitmapSource)source).PixelWidth;image.LayoutTransform=new ScaleTransform(scale,scale);};foreach(var label in new[]{"适应窗口","100%","－","＋","全屏"}) {string s=label;var b=new Button {Content=s};b.Click+=(a,e)=> {if(s=="适应窗口")fit();else if(s=="100%")zoom(1);else if(s=="－")zoom(scale/1.25);else if(s=="＋")zoom(scale*1.25);else {bool full=w.WindowStyle==WindowStyle.None;w.WindowStyle=full?WindowStyle.SingleBorderWindow:WindowStyle.None;w.WindowState=full?WindowState.Normal:WindowState.Maximized;fit();}};tools.Children.Add(b);}grid.Children.Add(tools);Grid.SetRow(scroll,1);grid.Children.Add(scroll);w.Content=grid;w.Loaded+=(s,e)=>fit();w.KeyDown+=(s,e)=> {if(e.Key==Key.Escape) {if(w.WindowStyle==WindowStyle.None){w.WindowStyle=WindowStyle.SingleBorderWindow;w.WindowState=WindowState.Normal;}else w.Close();}};scroll.PreviewMouseWheel+=(s,e)=> {if(Keyboard.Modifiers==ModifierKeys.Control){zoom(scale*(e.Delta>0?1.2:1/1.2));e.Handled=true;}};w.Show();}
  public static async Task Compare(Window owner,VideoItem item,int center,Finding finding,Action<double> locate,Action<string,bool> label) {
   var w=Dialog(owner,"连续帧对照 · "+item.Name,1280,820);var grid=new Grid {Margin=new Thickness(12)};grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition {Height=GridLength.Auto});
   var hint=new TextBlock {Text="前后各五帧：点击缩略图放大，并同步定位主窗口。中心帧以橙色边框标记。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10)};grid.Children.Add(hint);var large=new Image {Stretch=Stretch.Uniform};var bg=new Border {Background=Brushes.Black,Child=large};Grid.SetRow(bg,1);grid.Children.Add(bg);var strip=new StackPanel {Orientation=Orientation.Horizontal};var scroll=new ScrollViewer {Content=strip,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled,Margin=new Thickness(0,10,0,8)};Grid.SetRow(scroll,2);grid.Children.Add(scroll);
   var controls=new WrapPanel();var kinds=new ComboBox {Width=90,Margin=new Thickness(0,0,10,0)};kinds.ItemsSource=new[]{"夹帧","黑屏"};kinds.SelectedItem=finding==null?"夹帧":finding.Kind;controls.Children.Add(kinds);foreach(bool error in new[]{true,false}) {bool value=error;var b=new Button {Content=value?"保存为异常校准样本":"保存为正常校准样本"};b.Click+=(s,e)=> {label(kinds.SelectedItem.ToString(),value);hint.Text="样本已保存。可在主窗口“样本校准”中评估灵敏度。";};controls.Children.Add(b);}var open=new Button {Content="独立放大"};open.Click+=(s,e)=> {if(large.Source!=null)Zoom(w,large.Source,item.Name);};controls.Children.Add(open);Grid.SetRow(controls,3);grid.Children.Add(controls);w.Content=grid;var cancel=new CancellationTokenSource();w.Closed+=(s,e)=>cancel.Cancel();w.Show();
   int count=item.Result==null?Math.Max(1,(int)Math.Round(item.Info.Duration*item.Info.Fps)):item.Result.FrameCount;
   for(int i=Math.Max(0,center-5);i<=Math.Min(count-1,center+5);i++) {int index=i;double time=item.Result!=null?item.Result.Times[index]:index/item.Info.Fps;try {var bytes=await Task.Run(()=>Detector.Preview(item.Path,time,cancel.Token));if(cancel.IsCancellationRequested)return;var bitmap=Bitmap(bytes);var stack=new StackPanel();stack.Children.Add(new Image {Source=bitmap,Height=85,Width=130,Stretch=Stretch.Uniform});stack.Children.Add(new TextBlock {Text="第 "+(index+1)+" 帧 · "+Util.Time(time),FontSize=10,TextAlignment=TextAlignment.Center,Margin=new Thickness(0,6,0,0)});var b=new Button {Content=stack,Padding=new Thickness(4),BorderBrush=index==center?Brushes.Orange:Brushes.SlateGray,Margin=new Thickness(0,0,7,0)};b.Click+=(s,e)=> {large.Source=bitmap;locate(time);};strip.Children.Add(b);if(index==center){large.Source=bitmap;b.BringIntoView();}}catch(OperationCanceledException){return;}catch(Exception ex){hint.Text="部分帧读取失败："+ex.Message;}}
  }
 }
}
